-- Additive-only normalized schema. Existing legacy balances and rows are preserved.
CREATE TABLE IF NOT EXISTS "Profile" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL UNIQUE,"legalFirstName" TEXT NOT NULL,"legalLastName" TEXT NOT NULL,"displayName" TEXT,"username" TEXT NOT NULL UNIQUE,"phone" TEXT NOT NULL UNIQUE,"email" TEXT NOT NULL UNIQUE,"avatarUrl" TEXT,"preferences" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Profile_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE IF NOT EXISTS "Identity" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL UNIQUE,"status" TEXT NOT NULL DEFAULT 'UNVERIFIED',"ninLast4" TEXT,"ninProvider" TEXT,"ninProviderReference" TEXT,"ninVerifiedAt" TIMESTAMP(3),"faceStatus" TEXT NOT NULL DEFAULT 'NOT_CONFIGURED',"faceProvider" TEXT,"faceProviderReference" TEXT,"faceVerifiedAt" TIMESTAMP(3),"lockedLegalName" TEXT,"lastFailureCode" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Identity_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE IF NOT EXISTS "Account" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL UNIQUE,"accountNumber" TEXT NOT NULL UNIQUE,"currency" TEXT NOT NULL DEFAULT 'NGN',"balanceKobo" BIGINT NOT NULL DEFAULT 0,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Account_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX IF NOT EXISTS "Account_status_updatedAt_idx" ON "Account"("status","updatedAt");
CREATE TABLE IF NOT EXISTS "Device" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"credentialId" TEXT NOT NULL UNIQUE,"publicKeyBase64" TEXT NOT NULL,"counter" BIGINT NOT NULL DEFAULT 0,"transports" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],"deviceType" TEXT NOT NULL DEFAULT 'UNKNOWN',"backedUp" BOOLEAN NOT NULL DEFAULT FALSE,"label" TEXT,"lastUsedAt" TIMESTAMP(3),"revokedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Device_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX IF NOT EXISTS "Device_userId_revokedAt_idx" ON "Device"("userId","revokedAt");
CREATE TABLE IF NOT EXISTS "WebAuthnChallenge" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"challenge" TEXT NOT NULL,"purpose" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"consumedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "WebAuthnChallenge_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX IF NOT EXISTS "WebAuthnChallenge_userId_purpose_expiresAt_idx" ON "WebAuthnChallenge"("userId","purpose","expiresAt");
CREATE TABLE IF NOT EXISTS "TransactionEvent" ("id" TEXT PRIMARY KEY,"transactionId" TEXT NOT NULL,"actorUserId" TEXT,"eventType" TEXT NOT NULL,"eventKey" TEXT UNIQUE,"fromStatus" TEXT,"toStatus" TEXT,"provider" TEXT,"providerRef" TEXT,"payloadHash" TEXT,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "TransactionEvent_transactionId_fkey" FOREIGN KEY("transactionId") REFERENCES "Transaction"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "TransactionEvent_actorUserId_fkey" FOREIGN KEY("actorUserId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE INDEX IF NOT EXISTS "TransactionEvent_transactionId_createdAt_idx" ON "TransactionEvent"("transactionId","createdAt");
CREATE INDEX IF NOT EXISTS "TransactionEvent_provider_providerRef_idx" ON "TransactionEvent"("provider","providerRef");
CREATE TABLE IF NOT EXISTS "Receipt" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"transactionId" TEXT NOT NULL,"reference" TEXT NOT NULL UNIQUE,"kind" TEXT NOT NULL,"snapshot" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Receipt_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "Receipt_transactionId_fkey" FOREIGN KEY("transactionId") REFERENCES "Transaction"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX IF NOT EXISTS "Receipt_userId_createdAt_idx" ON "Receipt"("userId","createdAt");
CREATE INDEX IF NOT EXISTS "Receipt_transactionId_idx" ON "Receipt"("transactionId");
CREATE TABLE IF NOT EXISTS "Upgrade" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"level" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'PENDING',"entitlementSet" JSONB,"requestedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"activatedAt" TIMESTAMP(3),"expiresAt" TIMESTAMP(3),"reviewedBy" TEXT,"reviewNote" TEXT,CONSTRAINT "Upgrade_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX IF NOT EXISTS "Upgrade_userId_status_requestedAt_idx" ON "Upgrade"("userId","status","requestedAt");
CREATE TABLE IF NOT EXISTS "AuditLog" ("id" TEXT PRIMARY KEY,"actorUserId" TEXT,"targetUserId" TEXT,"action" TEXT NOT NULL,"entityType" TEXT,"entityId" TEXT,"outcome" TEXT NOT NULL DEFAULT 'SUCCESS',"ipAddress" TEXT,"userAgent" TEXT,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AuditLog_actorUserId_fkey" FOREIGN KEY("actorUserId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE INDEX IF NOT EXISTS "AuditLog_actorUserId_createdAt_idx" ON "AuditLog"("actorUserId","createdAt");
CREATE INDEX IF NOT EXISTS "AuditLog_targetUserId_createdAt_idx" ON "AuditLog"("targetUserId","createdAt");
CREATE INDEX IF NOT EXISTS "AuditLog_action_createdAt_idx" ON "AuditLog"("action","createdAt");
-- Ensure only one OWNER role can exist; this partial index is PostgreSQL-specific.
CREATE UNIQUE INDEX IF NOT EXISTS "User_one_owner_only_idx" ON "User" ((1)) WHERE "role" = 'OWNER';
-- Backfill from the existing database without overwriting existing balances.
INSERT INTO "Profile" ("id","userId","legalFirstName","legalLastName","username","phone","email","avatarUrl","createdAt","updatedAt") SELECT 'prof_'||md5(u."id"),u."id",u."firstName",u."lastName",u."username",u."phone",u."email",u."profileImageUrl",u."createdAt",CURRENT_TIMESTAMP FROM "User" u ON CONFLICT("userId") DO NOTHING;
INSERT INTO "Identity" ("id","userId","status","ninLast4","faceStatus","createdAt","updatedAt") SELECT 'ident_'||md5(u."id"),u."id",COALESCE(u."identityStatus",'UNVERIFIED'),u."ninLast4",COALESCE(u."faceVerificationStatus",'NOT_CONFIGURED'),u."createdAt",CURRENT_TIMESTAMP FROM "User" u ON CONFLICT("userId") DO NOTHING;
INSERT INTO "Account" ("id","userId","accountNumber","currency","balanceKobo","status","createdAt","updatedAt") SELECT 'acct_'||md5(u."id"),u."id",u."accountNumber",COALESCE(w."currency",'NGN'),ROUND(COALESCE(w."balance",0)*100)::BIGINT,COALESCE(w."status",'ACTIVE'),u."createdAt",CURRENT_TIMESTAMP FROM "User" u LEFT JOIN "Wallet" w ON w."userId"=u."id" ON CONFLICT("userId") DO NOTHING;
